      const isChat = !req.url?.endsWith("/models");
      if (isChat) race.chats++;
      if (opts.always || race.killAll || nth > 1) {
        race.killed++;
        req.socket.destroy();
        return;
      }
      race.answered++;
      if (!isChat) {
        res.setHeader("content-type", "application/json");
        res.end(JSON.stringify({ data: [{ id: "m" }] }));
        return;
